// #190: docs/ui-guide.md 공통 값(uiStyles, ConfirmModal, FieldError, ListStatus, writer)으로 바꿨다.
import { useEffect, useState, type FormEvent, type KeyboardEvent } from "react";
import { Link, useNavigate } from "react-router-dom";
import { getErrorCode, getErrorMessage, getFieldErrors } from "../api/client";
import { withdraw } from "../api/member";
import { getMyInfo, updatePrivate, type MyInfo, type PrivateUpdateRequest } from "../api/mypage";
import ConfirmModal from "../components/ConfirmModal";
import FieldError from "../components/FieldError";
import Header from "../components/Header";
import ListStatus from "../components/ListStatus";
import { buttonClass, CARD, FOCUS, INPUT, NOTICE, PAGE_BACKGROUND } from "../components/uiStyles";
import { formatDate } from "../components/writer";
import { useAuth } from "../hooks/useAuth";
import "./AccountEdit.css";

// 서버(member.constants.js)와 같은 입력값 규칙 (docs/api.md 입력값 규칙)
const PASSWORD_PATTERN = /^[A-Za-z0-9_.-]{8,12}$/;
const PHONE_PATTERN = /^01[0-9]{8,9}$/;

type Field = "currentPassword" | "newPassword" | "passwordConfirm" | "phone";
type Errors = Partial<Record<Field | "form", string>>;

const SERVER_FIELDS: Record<string, Field> = {
  currentPassword: "currentPassword",
  newPassword: "newPassword",
  phone: "phone",
};

const ICON = "material-symbols-outlined text-[18px] leading-none shrink-0";
const CARD_PADDING = "p-4 sm:p-6";
// 라벨 왼쪽, 입력칸 오른쪽 (휴대폰 폭에서는 위아래)
const ROW = "grid grid-cols-1 sm:grid-cols-12 gap-1.5 sm:gap-4 items-start";
const ROW_LABEL = `${INPUT.label} sm:col-span-3 sm:mb-0 sm:pt-3`;
const ROW_FIELD = "sm:col-span-9";

// 01012345678 → 010-1234-5678, 0101234567 → 010-123-4567 (입력 중에도 자동으로 하이픈을 넣는다)
function formatPhone(value: string) {
  const digits = value.replace(/\D/g, "").slice(0, 11);
  if (digits.length < 4) return digits;
  if (digits.length < 8) return `${digits.slice(0, 3)}-${digits.slice(3)}`;
  const middle = digits.length === 11 ? 4 : 3;
  return `${digits.slice(0, 3)}-${digits.slice(3, 3 + middle)}-${digits.slice(3 + middle)}`;
}

function validate(
  values: Record<Field, string>,
  currentPhone: string,
): { errors: Errors; request?: PrivateUpdateRequest } {
  const errors: Errors = {};
  const phone = values.phone.replace(/-/g, "");
  const changingPassword = values.newPassword !== "" || values.passwordConfirm !== "";
  const changingPhone = phone !== currentPhone;

  if (values.currentPassword === "") {
    errors.currentPassword = "저장하려면 현재 비밀번호를 입력해 주세요.";
  }
  if (!PHONE_PATTERN.test(phone)) {
    errors.phone = "01로 시작하는 10~11자리 숫자로 입력해 주세요.";
  }
  if (changingPassword) {
    if (!PASSWORD_PATTERN.test(values.newPassword)) {
      errors.newPassword = "8~12자, 영문·숫자와 특수기호 _ . - 만 사용할 수 있어요.";
    } else if (values.newPassword !== values.passwordConfirm) {
      errors.passwordConfirm = "새 비밀번호와 일치하지 않아요.";
    }
  }
  if (!changingPassword && !changingPhone && !errors.phone) {
    errors.form = "바꿀 내용이 없어요. 새 비밀번호나 전화번호를 입력해 주세요.";
  }
  if (Object.keys(errors).length > 0) {
    return { errors };
  }
  return {
    errors,
    request: {
      currentPassword: values.currentPassword,
      ...(changingPassword && { newPassword: values.newPassword }),
      ...(changingPhone && { phone }),
    },
  };
}

// 비밀번호 입력칸 (숨김 상태가 기본, 눈 아이콘으로 표시/숨김 전환)
function PasswordInput(props: {
  id: string;
  placeholder: string;
  value: string;
  error?: string;
  autoComplete: string;
  autoFocus?: boolean;
  onChange: (value: string) => void;
  onEnter?: () => void;
}) {
  const [visible, setVisible] = useState(false);
  const errorId = `${props.id}-error`;
  return (
    <>
      <div className="relative">
        <input
          aria-describedby={props.error ? errorId : undefined}
          aria-invalid={Boolean(props.error)}
          autoComplete={props.autoComplete}
          autoFocus={props.autoFocus}
          className={`${INPUT.base} pr-11 ${props.error ? INPUT.error : ""}`}
          id={props.id}
          onChange={(e) => props.onChange(e.target.value)}
          onKeyDown={(e: KeyboardEvent<HTMLInputElement>) => {
            if (e.key === "Enter" && props.onEnter) {
              e.preventDefault();
              props.onEnter();
            }
          }}
          placeholder={props.placeholder}
          type={visible ? "text" : "password"}
          value={props.value}
        />
        <button
          aria-label={visible ? "비밀번호 숨기기" : "비밀번호 보기"}
          aria-pressed={visible}
          className={`absolute inset-y-0 right-1 my-1 px-2 flex items-center rounded text-devin-gray hover:text-devin-ink ${FOCUS}`}
          onClick={() => setVisible((v) => !v)}
          type="button"
        >
          <span className={ICON} aria-hidden="true">
            {visible ? "visibility_off" : "visibility"}
          </span>
        </button>
      </div>
      <div id={errorId}>
        <FieldError message={props.error} />
      </div>
    </>
  );
}

// 회원 탈퇴 구역 (REQ-MYPAGE-009, 010). 저장 폼과 따로 둔다.
function WithdrawSection({ onOpen }: { onOpen: () => void }) {
  return (
    <section
      className={`mt-10 ${CARD_PADDING} rounded-xl border-devin border-dashed border-devin-red bg-devin-red-soft`}
      data-purpose="withdraw-section"
    >
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h2 className="mb-2 text-base font-extrabold text-devin-red">회원 탈퇴</h2>
          <ul className="space-y-1 text-xs text-devin-ink leading-relaxed list-disc pl-4">
            <li>
              탈퇴하면 <strong>되돌릴 수 없어요.</strong>
            </li>
            <li>
              작성한 질문·답변·답글은 남고, 작성자는 <strong>"탈퇴한 회원"</strong>으로 보여요.
            </li>
            <li>프로필·관심 카테고리·알림은 모두 지워져요.</li>
          </ul>
        </div>
        <button className={`${buttonClass("danger")} shrink-0`} onClick={onOpen} type="button">
          회원 탈퇴
        </button>
      </div>
    </section>
  );
}

// 이중 확인: 비밀번호 입력 + 동의 체크를 모두 해야 탈퇴한다.
function WithdrawDialog({ onClose, onWithdrawn }: { onClose: () => void; onWithdrawn: () => void }) {
  const [password, setPassword] = useState("");
  const [agreed, setAgreed] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);

  async function handleConfirm() {
    if (submitting) return;
    if (password === "") {
      setError("탈퇴하려면 현재 비밀번호를 입력해 주세요.");
      return;
    }
    if (!agreed) {
      setError("안내 내용을 확인하고 탈퇴에 동의해 주세요.");
      return;
    }
    setSubmitting(true);
    setError(null);
    try {
      await withdraw(password);
      onWithdrawn();
    } catch (err) {
      setError(
        getErrorCode(err) === "PASSWORD_MISMATCH"
          ? "현재 비밀번호가 일치하지 않아요."
          : getErrorMessage(err, "탈퇴를 처리하지 못했어요. 잠시 후 다시 시도해 주세요."),
      );
      setSubmitting(false);
    }
  }

  return (
    <ConfirmModal
      busy={submitting}
      confirmLabel="탈퇴하기"
      error={error}
      message='탈퇴하면 계정을 되돌릴 수 없어요. 작성한 글은 "탈퇴한 회원" 이름으로 남아요.'
      onCancel={onClose}
      onConfirm={handleConfirm}
      retryable
      title="정말 탈퇴할까요?"
      tone="danger"
    >
      <label className={INPUT.label} htmlFor="withdraw-password">
        비밀번호 확인
      </label>
      <PasswordInput
        autoComplete="current-password"
        id="withdraw-password"
        onChange={(value) => {
          setPassword(value);
          setError(null);
        }}
        onEnter={handleConfirm}
        placeholder="현재 비밀번호 입력"
        value={password}
      />
      <label className="mt-4 flex items-start gap-2 text-sm font-semibold cursor-pointer">
        <input
          checked={agreed}
          className={`mt-0.5 w-4 h-4 rounded border-devin border-devin-ink text-devin-ink focus:ring-0 ${FOCUS}`}
          onChange={(e) => {
            setAgreed(e.target.checked);
            setError(null);
          }}
          type="checkbox"
        />
        <span>위 내용을 확인했고, 탈퇴에 동의해요.</span>
      </label>
    </ConfirmModal>
  );
}

const EMPTY_VALUES: Record<Field, string> = { currentPassword: "", newPassword: "", passwordConfirm: "", phone: "" };

export default function AccountEdit() {
  const navigate = useNavigate();
  const { user, initializing, logout } = useAuth();
  const [me, setMe] = useState<MyInfo | null>(null);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [values, setValues] = useState(EMPTY_VALUES);
  const [errors, setErrors] = useState<Errors>({});
  const [submitting, setSubmitting] = useState(false);
  const [completed, setCompleted] = useState(false);
  const [withdrawStep, setWithdrawStep] = useState<"closed" | "confirm" | "done">("closed");

  // 탈퇴 후: 이 브라우저의 로그인 상태를 지우고 로그인 화면으로 보낸다.
  async function finishWithdraw() {
    await logout();
    navigate("/login", { replace: true });
  }

  // 로그인이 필요한 화면이다. 새로고침 직후에는 reissue로 로그인 상태를 복구할 때까지 기다린다.
  useEffect(() => {
    if (!initializing && !user) {
      navigate("/login", { replace: true });
    }
  }, [initializing, user, navigate]);

  useEffect(() => {
    if (!user) return;
    let cancelled = false;
    getMyInfo()
      .then((info) => {
        if (cancelled) return;
        setMe(info);
        setValues({ ...EMPTY_VALUES, phone: formatPhone(info.phone) });
      })
      .catch((error) => {
        if (!cancelled)
          setLoadError(getErrorMessage(error, "내 정보를 불러오지 못했어요. 잠시 후 다시 시도해 주세요."));
      });
    return () => {
      cancelled = true;
    };
  }, [user]);

  const change = (field: Field) => (value: string) => {
    setValues((prev) => ({ ...prev, [field]: field === "phone" ? formatPhone(value) : value }));
    setErrors((prev) => ({ ...prev, [field]: undefined, form: undefined }));
  };

  async function handleSubmit(e: FormEvent) {
    e.preventDefault();
    if (!me || submitting) return;
    const { errors: found, request } = validate(values, me.phone);
    setErrors(found);
    if (!request) return;

    setSubmitting(true);
    try {
      await updatePrivate(request);
      setMe({ ...me, phone: request.phone ?? me.phone });
      setValues((prev) => ({ ...EMPTY_VALUES, phone: prev.phone }));
      setCompleted(true);
    } catch (error) {
      const code = getErrorCode(error);
      if (code === "PASSWORD_MISMATCH") {
        setErrors({ currentPassword: "현재 비밀번호가 일치하지 않아요." });
      } else if (code === "DUPLICATE_PHONE") {
        setErrors({ phone: "이미 가입된 전화번호예요." });
      } else if (code === "INVALID_INPUT") {
        const next: Errors = {};
        getFieldErrors(error).forEach(({ field, reason }) => {
          next[SERVER_FIELDS[field] ?? "form"] = reason;
        });
        setErrors(Object.keys(next).length > 0 ? next : { form: getErrorMessage(error) });
      } else {
        setErrors({ form: getErrorMessage(error) });
      }
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <div id="page-account-edit">
      <div className={`${PAGE_BACKGROUND} min-h-screen flex flex-col text-devin-ink antialiased`}>
        <Header />
        <main className="flex-1 w-full max-w-3xl mx-auto px-4 sm:px-6 py-6" data-purpose="profile-edit-container">
          <header className="flex flex-wrap items-center justify-between gap-3 mb-6" data-purpose="header-section">
            <h1 className="text-2xl font-black">개인정보 수정</h1>
            <Link className={buttonClass("secondary", "sm")} to="/mypage">
              <span className={ICON} aria-hidden="true">
                arrow_back
              </span>
              마이페이지
            </Link>
          </header>

          {loadError && (
            <p className={NOTICE.error} role="alert">
              <span className={ICON} aria-hidden="true">
                error
              </span>
              {loadError}
            </p>
          )}
          {!me && !loadError && <ListStatus kind="loading">내 정보를 불러오는 중이에요.</ListStatus>}

          {me && (
            <form className="space-y-6" id="profile-edit-form" noValidate onSubmit={handleSubmit}>
              {/* 계정 정보 (수정 불가) */}
              <section className={`${CARD} ${CARD_PADDING} space-y-4`} data-purpose="account-identity-section">
                <div className={ROW}>
                  <label className={ROW_LABEL} htmlFor="username">
                    아이디
                  </label>
                  <div className={ROW_FIELD}>
                    <input
                      className={`${INPUT.base} font-mono`}
                      disabled
                      id="username"
                      type="text"
                      value={me.loginId}
                    />
                    <p className={INPUT.hint}>아이디는 바꿀 수 없어요.</p>
                  </div>
                </div>
                <div className={ROW}>
                  <span className={`${INPUT.label} sm:col-span-3 sm:mb-0`}>가입일</span>
                  <div className={`${ROW_FIELD} text-sm tabular-nums`}>{formatDate(me.createdAt)}</div>
                </div>
              </section>

              {/* 연락처 */}
              <section className={`${CARD} ${CARD_PADDING}`} data-purpose="contact-section">
                <div className={ROW}>
                  <label className={ROW_LABEL} htmlFor="phone-number">
                    전화번호
                  </label>
                  <div className={ROW_FIELD}>
                    <input
                      aria-invalid={Boolean(errors.phone)}
                      autoComplete="tel"
                      className={`${INPUT.base} font-mono ${errors.phone ? INPUT.error : ""}`}
                      id="phone-number"
                      inputMode="numeric"
                      maxLength={13}
                      onChange={(e) => change("phone")(e.target.value)}
                      placeholder="010-0000-0000"
                      type="text"
                      value={values.phone}
                    />
                    {errors.phone ? (
                      <FieldError message={errors.phone} />
                    ) : (
                      <p className={INPUT.hint}>숫자만 입력하면 하이픈이 자동으로 들어가요.</p>
                    )}
                  </div>
                </div>
              </section>

              {/* 비밀번호 변경 */}
              <section className={`${CARD} ${CARD_PADDING}`} data-purpose="password-section">
                <h2 className="mb-4 text-lg font-extrabold">비밀번호 변경</h2>
                <div className="space-y-4">
                  <div className={ROW}>
                    <label className={ROW_LABEL} htmlFor="current-pwd">
                      현재 비밀번호
                    </label>
                    <div className={ROW_FIELD}>
                      <PasswordInput
                        autoComplete="current-password"
                        error={errors.currentPassword}
                        id="current-pwd"
                        onChange={change("currentPassword")}
                        placeholder="현재 비밀번호 입력 (필수)"
                        value={values.currentPassword}
                      />
                    </div>
                  </div>
                  <div className={ROW}>
                    <label className={ROW_LABEL} htmlFor="new-pwd">
                      새 비밀번호
                    </label>
                    <div className={ROW_FIELD}>
                      <PasswordInput
                        autoComplete="new-password"
                        error={errors.newPassword}
                        id="new-pwd"
                        onChange={change("newPassword")}
                        placeholder="바꿀 때만 입력"
                        value={values.newPassword}
                      />
                    </div>
                  </div>
                  <div className={ROW}>
                    <label className={ROW_LABEL} htmlFor="confirm-pwd">
                      새 비밀번호 확인
                    </label>
                    <div className={ROW_FIELD}>
                      <PasswordInput
                        autoComplete="new-password"
                        error={errors.passwordConfirm}
                        id="confirm-pwd"
                        onChange={change("passwordConfirm")}
                        placeholder="새 비밀번호 다시 입력"
                        value={values.passwordConfirm}
                      />
                    </div>
                  </div>
                </div>
                <div className={`${NOTICE.info} mt-5`}>
                  <span className={ICON} aria-hidden="true">
                    info
                  </span>
                  <ul className="space-y-1 text-xs font-medium">
                    <li>전화번호만 바꿀 때도 현재 비밀번호가 필요해요.</li>
                    <li>새 비밀번호는 8~12자, 특수기호는 _ . - 만 쓸 수 있어요.</li>
                  </ul>
                </div>
              </section>

              {errors.form && (
                <p className={NOTICE.error} role="alert">
                  <span className={ICON} aria-hidden="true">
                    error
                  </span>
                  {errors.form}
                </p>
              )}

              <div className="flex items-center justify-end gap-2" data-purpose="form-actions">
                <button className={buttonClass("secondary")} onClick={() => navigate("/mypage")} type="button">
                  취소
                </button>
                <button className={buttonClass("primary")} disabled={submitting} type="submit">
                  {submitting ? "저장 중..." : "저장"}
                </button>
              </div>
            </form>
          )}
          {me && <WithdrawSection onOpen={() => setWithdrawStep("confirm")} />}
        </main>
      </div>
      {completed && (
        <ConfirmModal
          message="바꾼 내용은 바로 적용돼요."
          onCancel={() => setCompleted(false)}
          title="개인정보를 바꿨어요"
        />
      )}
      {withdrawStep === "confirm" && (
        <WithdrawDialog onClose={() => setWithdrawStep("closed")} onWithdrawn={() => setWithdrawStep("done")} />
      )}
      {withdrawStep === "done" && (
        <ConfirmModal
          message="그동안 Dev in_을 이용해 주셔서 감사해요."
          onCancel={finishWithdraw}
          title="탈퇴가 끝났어요"
        />
      )}
    </div>
  );
}
